DECLARE packs jsonb := $pack$[{"codigo":"S22H-C01","legacy_id":232,"legacy_ids":[232],"relacionadas":["S10-C15","S10-C14"],"residual":"","coberturas":[{"legacy_id":232,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"Ante presentación de aliado B2B mediante logo, nombre u oferta en producto BLOQUEAR cuando authorization_status no sea approved, incluyendo pending, draft, rejected, unknown o ausencia de evidencia. No inventar estado ni autorización. S10-C15 conserva autorización documentada para prototipos; S10-C14 conserva condiciones de oferta autorizadas. Binding pendiente."}],"hechos":["s22h01_presentacion_aliado","s22h01_estado_no_aprobado"],"paquete":{"tipo":"NUEVA","codigo":"S22H-C01","clave":"s22h_legacy_232","familia":"B2B_PARTNERS","naturaleza":"CONDUCTA","clase":"TRANSVERSAL","alcance":"BACKEND","modo":"HEREDA","dueno":"TECNICO","titulo":"Visibilidad de aliados autorizados","descripcion":"Ante presentación de aliado B2B mediante logo, nombre u oferta en producto BLOQUEAR cuando authorization_status no sea approved, incluyendo pending, draft, rejected, unknown o ausencia de evidencia. No inventar estado ni autorización. S10-C15 conserva autorización documentada para prototipos; S10-C14 conserva condiciones de oferta autorizadas. Binding pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/232","solicitante":"Cristhian / Claude S22-H 2026-11-25"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22h01_presentacion_aliado"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s22h01_estado_no_aprobado"},"der":{"lit":true}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s22h01_presentacion_aliado":true,"s22h01_estado_no_aprobado":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s22h01_presentacion_aliado":true,"s22h01_estado_no_aprobado":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22h01_presentacion_aliado":false,"s22h01_estado_no_aprobado":true},"esperado":false},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22h01_presentacion_aliado":false,"s22h01_estado_no_aprobado":false},"esperado":false}]},"hash":"19efdde10de4c4597b3c00b7f8b1f56713e85efa4cc239a722bf7ee6c6881bc3","hash_paquete":"73ead5ae785a840243e32da3506651409178257e69b5b304c765cd19178312d9","hash_evaluado":"19efdde10d","hash_paquete_10":"73ead5ae78"},{"codigo":"S22H-C02","legacy_id":214,"legacy_ids":[214,215,216],"relacionadas":[],"residual":"Falta acreditar que las rutas y métodos históricos coincidan con el contrato canónico vigente de onboarding.","coberturas":[{"legacy_id":214,"estado_cobertura":"PARCIAL","residual":"Falta acreditar que las rutas y métodos históricos coincidan con el contrato canónico vigente de onboarding.","diferencias":"Ante exposición de rutas API de onboarding, ofertas o pagos BLOQUEAR declarar disponibles endpoints históricos sin contrato vigente y binding verificado. En contrato autorizado exigir POST start, verify-otp, resend-otp; PATCH update-phone; GET home-variant de /api/v1/onboarding; GET /api/v1/offers; POST /api/v1/checkout/initiate y confirm; GET /api/v1/checkout/status/{id} y /api/v1/carta-no-adeudo/{offer_id}, únicamente si corresponden a rutas canónicas aprobadas. Start público; verify-otp, resend-otp y update-phone requieren contexto session_id validado server-side; ofertas, checkout y carta requieren autenticación JWT y autorización efectiva de recurso. No convierte session_id aislado en autorización ni certifica endpoints existentes. Binding pendiente."},{"legacy_id":215,"estado_cobertura":"PARCIAL","residual":"Falta acreditar que las rutas y métodos históricos coincidan con el contrato canónico vigente de ofertas, pagos y documentos.","diferencias":"Ante exposición de rutas API de onboarding, ofertas o pagos BLOQUEAR declarar disponibles endpoints históricos sin contrato vigente y binding verificado. En contrato autorizado exigir POST start, verify-otp, resend-otp; PATCH update-phone; GET home-variant de /api/v1/onboarding; GET /api/v1/offers; POST /api/v1/checkout/initiate y confirm; GET /api/v1/checkout/status/{id} y /api/v1/carta-no-adeudo/{offer_id}, únicamente si corresponden a rutas canónicas aprobadas. Start público; verify-otp, resend-otp y update-phone requieren contexto session_id validado server-side; ofertas, checkout y carta requieren autenticación JWT y autorización efectiva de recurso. No convierte session_id aislado en autorización ni certifica endpoints existentes. Binding pendiente."},{"legacy_id":216,"estado_cobertura":"PARCIAL","residual":"Falta verificar contrato runtime de autenticación y autorización de todas las rutas históricas; no se afirma equivalencia física.","diferencias":"Ante exposición de rutas API de onboarding, ofertas o pagos BLOQUEAR declarar disponibles endpoints históricos sin contrato vigente y binding verificado. En contrato autorizado exigir POST start, verify-otp, resend-otp; PATCH update-phone; GET home-variant de /api/v1/onboarding; GET /api/v1/offers; POST /api/v1/checkout/initiate y confirm; GET /api/v1/checkout/status/{id} y /api/v1/carta-no-adeudo/{offer_id}, únicamente si corresponden a rutas canónicas aprobadas. Start público; verify-otp, resend-otp y update-phone requieren contexto session_id validado server-side; ofertas, checkout y carta requieren autenticación JWT y autorización efectiva de recurso. No convierte session_id aislado en autorización ni certifica endpoints existentes. Binding pendiente."}],"hechos":["s22h02_exposicion_api","s22h02_contrato_o_binding_no_verificado","s22h02_ruta_o_metodo_no_autorizado","s22h02_contexto_autorizacion_invalido"],"paquete":{"tipo":"NUEVA","codigo":"S22H-C02","clave":"s22h_legacy_214","familia":"SECURITY","naturaleza":"CONDUCTA","clase":"TRANSVERSAL","alcance":"BACKEND","modo":"HEREDA","dueno":"TECNICO","titulo":"Contratos históricos de rutas API con autorización por contexto","descripcion":"Ante exposición de rutas API de onboarding, ofertas o pagos BLOQUEAR declarar disponibles endpoints históricos sin contrato vigente y binding verificado. En contrato autorizado exigir POST start, verify-otp, resend-otp; PATCH update-phone; GET home-variant de /api/v1/onboarding; GET /api/v1/offers; POST /api/v1/checkout/initiate y confirm; GET /api/v1/checkout/status/{id} y /api/v1/carta-no-adeudo/{offer_id}, únicamente si corresponden a rutas canónicas aprobadas. Start público; verify-otp, resend-otp y update-phone requieren contexto session_id validado server-side; ofertas, checkout y carta requieren autenticación JWT y autorización efectiva de recurso. No convierte session_id aislado en autorización ni certifica endpoints existentes. Binding pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/214;lf_ops.reglas/215;lf_ops.reglas/216","solicitante":"Cristhian / Claude S22-H 2026-11-25"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"s22h02_exposicion_api"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"s22h02_contrato_o_binding_no_verificado"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"s22h02_ruta_o_metodo_no_autorizado"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"s22h02_contexto_autorizacion_invalido"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"s22h02_exposicion_api":true,"s22h02_contrato_o_binding_no_verificado":false,"s22h02_ruta_o_metodo_no_autorizado":false,"s22h02_contexto_autorizacion_invalido":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"s22h02_exposicion_api":true,"s22h02_contrato_o_binding_no_verificado":true,"s22h02_ruta_o_metodo_no_autorizado":false,"s22h02_contexto_autorizacion_invalido":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22h02_exposicion_api":true,"s22h02_contrato_o_binding_no_verificado":false,"s22h02_ruta_o_metodo_no_autorizado":true,"s22h02_contexto_autorizacion_invalido":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"s22h02_exposicion_api":true,"s22h02_contrato_o_binding_no_verificado":false,"s22h02_ruta_o_metodo_no_autorizado":false,"s22h02_contexto_autorizacion_invalido":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"s22h02_exposicion_api":false,"s22h02_contrato_o_binding_no_verificado":true,"s22h02_ruta_o_metodo_no_autorizado":true,"s22h02_contexto_autorizacion_invalido":true},"esperado":false}]},"hash":"b4a666d4601e41f6bc10dcf9cac392d1292a3e946a62d463b3f18d47bb5381e1","hash_paquete":"6d1303bcc34eb6b06c6ebf54adf00e058fcbf3a665a524a9942b5d15db49f5a7","hash_evaluado":"b4a666d460","hash_paquete_10":"6d1303bcc3"}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; t record; n int:=0; vectors int:=0; b_leg jsonb; b_dep jsonb; b_cfg jsonb; val jsonb; lid int; residual text; diff text; old_desc text; new_desc text; links int:=0; before_replaced int; after_replaced int; direct_hash text; c jsonb;
BEGIN
 SELECT count(DISTINCT legacy_id) INTO before_replaced FROM lf_ops.lf_nucleo_cobertura_legada WHERE estado_cobertura='REEMPLAZADA';
 SELECT jsonb_agg(to_jsonb(x) ORDER BY id) INTO b_leg FROM lf_ops.reglas x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) INTO b_dep FROM lf_ops.nucleo_deprecaciones x;
 SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) INTO b_cfg FROM public.lf_global_config x;
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true); h:=lf_ops.nucleo_hash_paquete_v1(cd,1);
 IF h IS DISTINCT FROM p->>'hash_paquete' OR NOT EXISTS(SELECT 1 FROM lf_ops.nucleo_regla_versiones WHERE regla=cd AND version=1 AND estado='CANDIDATA' AND hash=p->>'hash') THEN RAISE EXCEPTION 'S22_ATTESTATION_DRIFT %',cd; END IF;
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22_VECTOR_FAIL %',cd; END IF; vectors:=vectors+1; END LOOP;
 n:=n+1;
 END LOOP;
 IF n<>2 OR vectors<>9 THEN RAISE EXCEPTION 'S22_VECTOR_COUNT'; END IF;
 IF (SELECT jsonb_agg(to_jsonb(x) ORDER BY id) FROM lf_ops.reglas x) IS DISTINCT FROM b_leg OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY regla,version) FROM lf_ops.nucleo_deprecaciones x) IS DISTINCT FROM b_dep OR (SELECT jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text) FROM public.lf_global_config x) IS DISTINCT FROM b_cfg THEN RAISE EXCEPTION 'S22_INVARIANT_FAIL'; END IF;
 IF jsonb_array_length(lf_ops.lf_nucleo_lectura_transicion_v1(36,'INPUT_GOVERNANCE','DIRECTAS')->'nativas') IS DISTINCT FROM 0 THEN RAISE EXCEPTION 'S22_DPIG03_FAIL'; END IF;
 RAISE NOTICE 'S22H proposal-only: independent judgment pending';
END $s22$;
COMMIT;
